import { vec3, mat4 } from 'gl-matrix';
import { createTransforms, loadWGSL } from '../../../lib';

import { Geometry } from './Geometry';

import { Scene } from '../../Scene';
import { ObjectBase } from '../Base/ObjectBase';

// import vertPath from './shaders/vert.glsl';
// import fragPath from './shaders/frag.glsl';

import vertPath from './shaders/vert.glsl';
import fragPath from './shaders/frag.glsl';

export class NGeojsonLine extends ObjectBase {

    numberOfVertices: number = 0;
    vertexBuffer: any;
    colorBuffer: any;
    normalBuffer;
    uvBuffer;
    uniformBindGroup;
    uniformBindGroup1;
    uniformBindGroup2;
    uniformBuffer;

    commandEncoder;

    textureView;
    renderPassDescription;
    pipeline: GPURenderPipeline;

    isAnimation = false;

    mouseBuffer;
    frameBuffer;

    t: number = 0;

    resultBuffer;

    geometry: Geometry;

    posLoc;
    buf;
    buf2;
    colorLoc;

    frameLoc;
    mouseLoc;


    constructor(scene: Scene) {
        super(scene)


        this.init();
    }
    async init () {
        this.geometry = new Geometry();
        await this.geometry.init();
        // console.log(this.geometry)

        const vertShader = await loadWGSL(vertPath);
        const fragShader = await loadWGSL(fragPath);
        
        // const vertShader = vertPath // await loadWGSL(vertPath);
        // const fragShader = fragPath // await loadWGSL(fragPath);
        
        const gl = this.gl;

        this.vertexBuffer = gl.createBuffer();
        this.gl.bindBuffer(this.gl.ARRAY_BUFFER, this.vertexBuffer);
        gl.bufferData(gl.ARRAY_BUFFER, this.geometry.pos, gl.STATIC_DRAW);

        this.colorBuffer = gl.createBuffer();
        this.gl.bindBuffer(this.gl.ARRAY_BUFFER, this.colorBuffer);
        gl.bufferData(gl.ARRAY_BUFFER, this.geometry.colors, gl.STATIC_DRAW);


        this.program = gl.createProgram() as WebGLProgram;
        const vertexShader = gl.createShader(gl.VERTEX_SHADER) as WebGLShader;
        gl.shaderSource(vertexShader, vertShader as string);
        gl.compileShader(vertexShader);
        gl.attachShader(this.program, vertexShader);

        const fragmentShader = gl.createShader(gl.FRAGMENT_SHADER) as WebGLShader;
        gl.shaderSource(fragmentShader, fragShader as string);
        gl.compileShader(fragmentShader);
        gl.attachShader(this.program, fragmentShader);

        gl.linkProgram(this.program);


        // this.posLoc = gl.getAttribLocation(this.program, 'position');
        // this.colorLoc = gl.getAttribLocation(this.program, 'color');

        // this.buf = gl.createBuffer();
        // gl.bindBuffer(gl.ARRAY_BUFFER, this.buf);
        // gl.bufferData(gl.ARRAY_BUFFER, new Float32Array(this.geometry.pos), gl.STATIC_DRAW);
        // normally these would happen at render time


        // this.buf2 = gl.createBuffer();
        // gl.bindBuffer(gl.ARRAY_BUFFER, this.buf2);
        // gl.bufferData(gl.ARRAY_BUFFER, new Float32Array(this.geometry.colors), gl.STATIC_DRAW);

        
        this.modelLoc = gl.getUniformLocation(this.program, 'uModel') as WebGLUniformLocation;
        this.cameraLoc = gl.getUniformLocation(this.program, 'cameraProjection') as WebGLUniformLocation;

        
        this.frameLoc = gl.getUniformLocation(this.program, 'uFrame');
        this.mouseLoc = gl.getUniformLocation(this.program, 'uMouse');

        this.isRenderable = true;
    }
    render() {
        
        if (!this.isRenderable) { return; }
        // console.log('dd');
        // const gl = this.gl;
        createTransforms(this.modelMatrix, this.translation, this.rotation, this.scale);

        this.gl.useProgram(this.program);

        this.gl.bindBuffer(this.gl.ARRAY_BUFFER, this.vertexBuffer);
        this.gl.enableVertexAttribArray(0);
        this.gl.vertexAttribPointer(0, 3, this.gl.FLOAT, false, 0, 0);

        
        this.gl.bindBuffer(this.gl.ARRAY_BUFFER, this.colorBuffer);
        this.gl.enableVertexAttribArray(1);
        this.gl.vertexAttribPointer(1, 3, this.gl.FLOAT, false, 0, 0);
        

        this.gl.uniformMatrix4fv(this.modelLoc, false, this.modelMatrix);
        this.gl.uniformMatrix4fv(this.cameraLoc, false, this.scene.core.renderer.cameraController.getMatrix);

        this.gl.uniform1f(this.frameLoc, this.t);
        this.gl.uniform2f(this.mouseLoc, this.scene.core.renderer.cameraController.pos[0] * 0.01, this.scene.core.renderer.cameraController.pos[1] * 0.01);

        // console.log(this.scene.core.renderer.cameraController.pos);
        
        this.gl.drawArrays(this.gl.LINES, 0, this.geometry.pos.length / 3);

        this.t += 0.1;
    }
}
