import { Solution } from '../';

import { Renderer } from './Renderer';
import { Scene } from './Scene';

// import * as triangle from './Object/Tri/triangle';


export class Core {
    public id: string;
    public renderer: Renderer;
    public scene: Scene;

    constructor(id: string) {
        this.id = id;

        this.init();
    }
    async init() {
        this.renderer = new Renderer(this);
        this.scene = new Scene(this)
        this.scene.init();

        this.renderer.draw();
        
    }
    public destroy() {
        this.renderer.destroy();
        // console.log('destroy!!');
        // this.divHost.removeChild(this.canvas);

        if (this.renderer.divHost) {
            try {
                while (this.renderer.divHost.firstChild) {
                    this.renderer.divHost.removeChild(this.renderer.divHost.firstChild);
                }
            } catch (error) {
                console.error('Error in destroy method:', error);
            }
        } else {
            console.warn('divHost is undefined in destroy method');
        }
    }
}


